if name in _TASK_TOOLS:
    schema = next(
        t["function"]["parameters"]
        for t in task_management_tools()
        if t["function"]["name"] == name
    )
    if set(arguments) - set(schema["properties"]) or set(schema["required"]) - set(
        arguments
    ):
        raise ValueError("Invalid task tool arguments")
    for key, item in arguments.items():
        if key == "answers":
            if not isinstance(item, list) or not 1 <= len(item) <= 32:
                raise ValueError("Invalid answers")
        elif key in {"revision", "offset", "queue_version"}:
            if type(item) is not int or item < (1 if key == "revision" else 0):
                raise ValueError(f"Invalid {key}")
        elif (
            not isinstance(item, str)
            or not item.strip()
            or len(item) > (4000 if key == "instruction" else 256)
        ):
            raise ValueError(f"Invalid {key}")
    if name == "jiuwen_task_query" and "status" in arguments:
        if arguments["status"] not in schema["properties"]["status"]["enum"]:
            raise ValueError("Invalid task status")
    if name == "jiuwen_task_reorder":
        if arguments["action"] not in {"next", "before"}:
            raise ValueError("Invalid queue action: use next or before; before_job_id is a separate field")
        if (arguments["action"] == "before") != bool(
            arguments.get("before_job_id")
        ):
            raise ValueError("Only before requires before_job_id")
    return QwenOmniToolCall(name, call_id, arguments, "")

def task_management_tools():
    specs = [
        (
            "jiuwen_task_reorder",
            (
                "Reorder waiting tasks only, without stopping any running task. Query the queue first."
                " Clarify ambiguous targets. Priority never bypasses dependencies or resources and "
                "does not promise immediate execution."
                " Use returned opaque IDs, not task names. action must be exactly next or before;"
                " for before pass the other waiting task ID in the separate before_job_id field."
            ),
            {
                "job_id": {"type": "string"},
                "queue_version": {"type": "integer", "minimum": 0},
                "action": {"type": "string", "enum": ["next", "before"]},
                "before_job_id": {"type": "string"},
            },
            ["job_id", "queue_version", "action"],
        ),
        (
            "jiuwen_task_answer",
            (
                "Answer an observed pending Agent information question so the original task continues."
                " Query exact job_id, interaction.id and questions first; pass interaction.id as "
                "interaction_id. Clarify which task if ambiguous. Never use this for permission "
                "approvals or create a new task for an answer. answers is an array of plain text "
                "strings, one per observed question in the SAME order, e.g. [\"5000元\", \"2人\"]. "
                "Use only explicit user answers; ask for missing answers instead of inventing them. "
                "Accepted is not completed."
            ),
            {
                "job_id": {"type": "string"},
                "interaction_id": {"type": "string"},
                "answers": {
                    "type": "array",
                    "description": (
                        "Plain text answers in observed question order, e.g. [\"5000元\"]. "
                        "Answer every question exactly once; never copy or paraphrase the question."
                    ),
                    "minItems": 1,
                    "maxItems": 32,
                    "items": {"type": "string", "maxLength": 4000},
                },
            },
            ["job_id", "interaction_id", "answers"],
        ),
        (
            "jiuwen_task_query",
            (
                "Find tasks and their results in this conversation. Query before selecting an "
                "ambiguous task; use exact returned job_id and revision for controls. "
                "query is a literal substring of the original task text, not a question or "
                "a list of keywords. Prefer a known job_id. If no task matches, shorten query "
                "or list without query; no match does NOT prove completion or absence of files."
            ),
            {
                "job_id": {"type": "string"},
                "query": {"type": "string"},
                "offset": {"type": "integer", "minimum": 0},
                "status": {
                    "type": "string",
                    "enum": [
                        "queued", "running", "waiting_user", "cancelling", "unknown",
                        "completed", "failed", "cancelled", "unfinished",
                    ],
                },
            },
            [],
        ),
        (
            "jiuwen_task_cancel",
            "Request cancellation of the exact task. Accepted does not mean stopped. Query for the final state.",
            {"job_id": {"type": "string"}},
            ["job_id"],
        ),
        (
            "jiuwen_task_modify",
            (
                "Change the exact task's requirements. Queued input is updated; running changes wait "
                "for a model checkpoint; finished work creates a linked revision. Receipt never proves"
                " the requirement is satisfied."
            ),
            {
                "job_id": {"type": "string"},
                "revision": {"type": "integer", "minimum": 1},
                "instruction": {"type": "string", "maxLength": 4000},
            },
            ["job_id", "revision", "instruction"],
        ),
    ]
    return [
        {
            "type": "function",
            "function": {
                "name": name,
                "description": description,
                "parameters": {
                    "type": "object",
                    "properties": properties,
                    "required": required,
                    "additionalProperties": False,
                },
            },
        }
        for name, description, properties, required in specs
    ]

async def operate(self, owner, scope, call):
    args = call.arguments
    if call.name == "jiuwen_task_query":
        snapshot = self.snapshot(owner, scope)
        jobs = snapshot["jobs"]
        if args.get("job_id"):
            self.service.get(owner, scope, args["job_id"])  # Keep ownership validation.
            jobs = [t for t in jobs if t["id"] == args["job_id"]]
        else:
            query = args.get("query", "").casefold()
            jobs = [t for t in jobs if query in t["question"].casefold()]
        counts = {}
        for job in jobs:
            counts[job["status"]] = counts.get(job["status"], 0) + 1
        unfinished = sum(n for state, n in counts.items()
                         if state not in {"completed", "failed", "cancelled"})
        selected = jobs
        status = args.get("status", "")
        if status == "unfinished":
            selected = [t for t in jobs if t["status"] not in {"completed", "failed", "cancelled"}]
        elif status:
            selected = [t for t in jobs if t["status"] == status]
        offset = args.get("offset", 0)
        page = selected[offset:offset + 5]
        result = {
            **snapshot,
            "jobs": [self.voice_job(t) for t in page],
            "scope": {"session_id": scope, "job_id": args.get("job_id"),
                      "query": args.get("query", ""), "status": status},
            "summary": {"total": len(jobs), "status_counts": counts,
                        "unfinished": unfinished, "all_finished": bool(jobs) and unfinished == 0,
                        "all_succeeded": bool(jobs) and counts.get("completed", 0) == len(jobs)},
            "matched_total": len(selected),
            "next_offset": offset + 5 if offset + 5 < len(selected) else None,
            "message": task_query_instructions(len(jobs), counts, unfinished, len(page), len(selected)),
        }
        if not jobs:
            result["message"] = EMPTY_QUERY_INSTRUCTIONS
    elif call.name == "jiuwen_task_cancel":
        result = await self.service.cancel(
            owner, scope, args["job_id"], call.call_id
        )
    elif call.name == "jiuwen_task_reorder":
        if args["action"] == "before" and not args.get("before_job_id"):
            raise ValueError("before requires before_job_id")
        try:
            receipt = self.service.reorder(
                owner, scope, args["job_id"], args["queue_version"],
                args.get("before_job_id"), command_id=call.call_id,
            )
        except QueueVersionConflict as exc:
            receipt = dict(
                task_id=args["job_id"], state="rejected", applied=False,
                code="QUEUE_VERSION_CONFLICT", error=str(exc),
            )
        snapshot = self.snapshot(owner, scope)
        waiting = sorted((t for t in snapshot["jobs"] if t["status"] == "queued"),
                         key=lambda t: t["queue_position"])
        target = next(t for t in snapshot["jobs"] if t["id"] == args["job_id"])
        index = next((i for i, t in enumerate(waiting) if t["id"] == target["id"]), 0)
        result = {
            "operation": receipt,
            "queue_version": snapshot["queue_version"],
            "target": self.voice_job(target),
            "jobs": [self.voice_job(t) for t in waiting[max(0, index - 1):index + 4]],
            "waiting_total": len(waiting),
            "message": REORDER_INSTRUCTIONS,
        }
        if receipt.get("state") == "rejected":
            result.update(receipt, message=QUEUE_CONFLICT_INSTRUCTIONS)
    elif call.name == "jiuwen_task_answer":
        result = await self.service.answer(
            owner,
            scope,
            args["job_id"],
            call.call_id,
            args["interaction_id"],
            answers=args["answers"],
        )
    else:
        try:
            result = self.service.modify(
                owner, scope, args["job_id"], call.call_id,
                TaskModification(args["revision"], args["instruction"]),
            )
        except TaskRevisionConflict as exc:
            current = self.service.get(owner, scope, args["job_id"])
            result = dict(
                state="rejected", error=str(exc), applied=False,
                current_task=self.voice_job(self.public(current)),
                message=REVISION_CONFLICT_INSTRUCTIONS,
            )
    return result

"""Internal conflict types; human-readable wording is not a control protocol."""


class QueueVersionConflict(ValueError):
    """The waiting queue changed after the caller observed it."""


class TaskRevisionConflict(ValueError):
    """The task revision changed or already has a linked successor."""
